// ===== REASON ENGINE =====
// Analyzes user input and determines intent

const message = $input.first().json.message || '';
const url = $input.first().json.url || '';
const context = $input.first().json.context || {};
const isArabic = /[\u0600-\u06FF]/.test(message);

const lower = message.toLowerCase().trim();

// Extract URL from message if not provided directly
let extractedUrl = url;
if (!extractedUrl) {
  const urlMatch = lower.match(/https?:\/\/[^\s]+/) || lower.match(/(?:www\.)?([a-z0-9\-]+\.[a-z]{2,})/);
  if (urlMatch) {
    extractedUrl = urlMatch[0];
    if (!extractedUrl.startsWith('http')) extractedUrl = 'https://' + extractedUrl;
  }
}

let intent = {
  type: 'unknown',
  tools: [],
  template: null,
  url: extractedUrl,
  isAr: isArabic,
  reasoning: '',
  message: message
};

// HELP
if (lower === 'help' || lower === 'مساعدة' || lower === '?' || lower === '.help') {
  intent.type = 'help';
  intent.reasoning = 'User wants help';
  return [{ json: intent }];
}

// URL SCAN - just a URL pasted
if (!lower.match(/audit|full|speed|content|meta|image|link|heading|schema|robots|sitemap|score|keyword|competitor|product|quick|شامل|سرعة|محتوى|كلمات|صور|روابط|عنوان|هيكل|روبوت|خريطة|نتيجة|وسوم|منافس|منتجات|بحث|سريع/) && extractedUrl) {
  intent.type = 'template';
  intent.template = 'quick';
  intent.reasoning = 'URL provided without specific command - running quick scan';
  return [{ json: intent }];
}

// COMPLEX INTENTS
if (lower.indexOf('competitor') !== -1 || lower.indexOf('منافس') !== -1) {
  intent.type = 'multi';
  intent.tools = ['score', 'content', 'keywords', 'meta', 'competitor'];
  intent.reasoning = 'Competitor analysis needs content + keywords + meta comparison';
  return [{ json: intent }];
}

if (lower.indexOf('ecommerce') !== -1 || lower.indexOf('متجر') !== -1 || lower.indexOf('shop') !== -1 || lower.indexOf('store') !== -1) {
  intent.type = 'multi';
  intent.tools = ['score', 'meta', 'headings', 'schema', 'content', 'images', 'links', 'product-monitor', 'kw-research'];
  intent.reasoning = 'E-commerce audit needs product + SEO tools';
  return [{ json: intent }];
}

if (lower.indexOf('prepublish') !== -1 || lower.indexOf('قبل النشر') !== -1 || lower.indexOf('نشر') !== -1) {
  intent.type = 'multi';
  intent.tools = ['meta', 'headings', 'schema', 'content', 'keywords', 'images'];
  intent.reasoning = 'Pre-publish check needs content + meta + structure tools';
  return [{ json: intent }];
}

if (lower.indexOf('technical') !== -1 || lower.indexOf('تقني') !== -1) {
  intent.type = 'multi';
  intent.tools = ['schema', 'robots', 'sitemap', 'links', 'speed', 'audit'];
  intent.reasoning = 'Technical SEO needs crawlability + performance tools';
  return [{ json: intent }];
}

if (lower.indexOf('full') !== -1 || lower.indexOf('audit') !== -1 || lower.indexOf('شامل') !== -1 || lower.indexOf('report') !== -1 || lower.indexOf('تقرير') !== -1) {
  intent.type = 'template';
  intent.template = 'full';
  intent.reasoning = 'Full audit requires all available tools';
  return [{ json: intent }];
}

if (lower.indexOf('content') !== -1 || lower.indexOf('محتوى') !== -1) {
  intent.type = 'multi';
  intent.tools = ['content', 'keywords', 'kw-research', 'images', 'headings'];
  intent.reasoning = 'Content analysis needs text + keywords + images + headings';
  return [{ json: intent }];
}

// SINGLE TOOL INTENTS
const singleMap = [
  { keys: ['speed', 'سرعة', 'fast', 'أداء'], id: 'speed' },
  { keys: ['keyword', 'كلمات', 'الكلمات', 'مفتاح'], id: 'keywords' },
  { keys: ['schema', 'هيكل', 'هيكلي', 'structured'], id: 'schema' },
  { keys: ['robots', 'روبوت', 'بوت'], id: 'robots' },
  { keys: ['score', 'النتيجة', 'نقط', 'نقاط'], id: 'score' },
  { keys: ['meta', 'وسوم', 'الوسوم', 'title', 'description'], id: 'meta' },
  { keys: ['image', 'صور', 'الصور', 'صورة'], id: 'images' },
  { keys: ['link', 'روابط', 'الروابط', 'رابط'], id: 'links' },
  { keys: ['heading', 'عنوان', 'العناوين', 'headings', 'h1', 'h2'], id: 'headings' },
  { keys: ['sitemap', 'خريطة', 'الخريطة'], id: 'sitemap' },
  { keys: ['research', 'بحث', 'seo keywords'], id: 'kw-research' },
  { keys: ['product', 'منتجات', 'المنتجات', 'رصد'], id: 'product-monitor' }
];

for (const s of singleMap) {
  for (const k of s.keys) {
    if (lower.indexOf(k) !== -1) {
      intent.type = 'single';
      intent.tools = [s.id];
      intent.reasoning = 'User wants ' + s.id;
      return [{ json: intent }];
    }
  }
}

// TEMPLATE INTENTS
if (lower.indexOf('quick') !== -1 || lower.indexOf('سريع') !== -1) {
  intent.type = 'template';
  intent.template = 'quick';
  intent.reasoning = 'Quick scan requested';
  return [{ json: intent }];
}

// UNKNOWN
intent.type = 'unknown';
intent.reasoning = 'Could not determine intent';
return [{ json: intent }];

