// ===== BUILD TOOL PIPELINE =====
// Maps intent to SEO tool URLs to fetch

const intent = $input.first().json;
const baseUrl = 'https://seohub-proxy.mmetwily1.workers.dev';
const siteUrl = intent.url;

// Tool catalog: maps tool ID to proxy URL pattern
const toolCatalog = {
  'score':          { path: '/?url={site}', name: 'Score', nameAr: 'النتيجة', icon: '📊' },
  'meta':           { path: '/?url={site}', name: 'Meta Tags', nameAr: 'الوسوم', icon: '🏔️' },
  'headings':       { path: '/?url={site}', name: 'Headings', nameAr: 'العناوين', icon: '📉' },
  'schema':         { path: '/?url={site}', name: 'Schema', nameAr: 'الهيكل', icon: '🔧' },
  'audit':          { path: '/?url={site}', name: 'Audit', nameAr: 'المواضعية', icon: '🔍' },
  'speed':          { path: '/?url={site}', name: 'Speed', nameAr: 'السرعة', icon: '⚡' },
  'content':        { path: '/?url={site}', name: 'Content', nameAr: 'المحتوى', icon: '📝' },
  'keywords':       { path: '/?url={site}', name: 'Keywords', nameAr: 'الكلمات', icon: '🔑' },
  'images':         { path: '/?url={site}', name: 'Images', nameAr: 'الصور', icon: '🖼️' },
  'links':          { path: '/?url={site}', name: 'Links', nameAr: 'الروابط', icon: '🔗' },
  'robots':         { path: '/?url={site}', name: 'Robots', nameAr: 'البوت', icon: '🤖' },
  'sitemap':        { path: '/?url={site}', name: 'Sitemap', nameAr: 'الخريطة', icon: '🗺️' },
  'kw-research':    { path: '/?url={site}', name: 'KW Research', nameAr: 'بحث كلمات', icon: '🔎' },
  'product-monitor':{ path: '/?url={site}', name: 'Products', nameAr: 'المنتجات', icon: '🛒' },
  'competitor':     { path: '/?url={site}', name: 'Competitor', nameAr: 'المنافس', icon: '🎯' }
};

// Templates
const templates = {
  'quick': ['score', 'meta', 'headings', 'content', 'speed'],
  'full': ['score', 'meta', 'headings', 'schema', 'audit', 'speed', 'content', 'keywords', 'images', 'links', 'robots', 'sitemap'],
  'content': ['content', 'keywords', 'kw-research', 'images', 'headings'],
  'technical': ['schema', 'robots', 'sitemap', 'links', 'speed', 'audit'],
  'prepublish': ['meta', 'headings', 'schema', 'content', 'keywords', 'images'],
  'ecommerce': ['score', 'meta', 'headings', 'schema', 'content', 'images', 'links', 'product-monitor', 'kw-research']
};

// Determine tool list
let toolIds = [];
if (intent.template && templates[intent.template]) {
  toolIds = templates[intent.template];
} else if (intent.tools && intent.tools.length > 0) {
  toolIds = intent.tools;
}

// Build pipeline items
const pipeline = [];
for (const toolId of toolIds) {
  const tool = toolCatalog[toolId];
  if (tool && siteUrl) {
    pipeline.push({
      id: toolId,
      name: tool.name,
      nameAr: tool.nameAr,
      icon: tool.icon,
      url: baseUrl + tool.path.replace('{site}', encodeURIComponent(siteUrl))
    });
  }
}

return [{
  json: {
    intent: intent,
    pipeline: pipeline,
    siteUrl: siteUrl,
    isAr: intent.isAr
  }
}];

// ===== EXECUTE TOOLS SEQUENTIALLY =====
// Fetches each tool's output via the proxy

const input = $input.first().json;
const pipeline = input.pipeline || [];
const siteUrl = input.siteUrl;
const intent = input.intent;
const isAr = input.isAr;

if (pipeline.length === 0) {
  return [{
    json: {
      intent: intent,
      results: {},
      done: 0,
      errors: 0,
      pipeline: [],
      isAr: isAr
    }
  }];
}

const results = {};
let done = 0;
let errors = 0;

// Execute each tool
for (const step of pipeline) {
  try {
    const response = await fetch(step.url, {
      headers: {
        'User-Agent': 'SEOHUB-Agent/1.0'
      }
    });
    const data = await response.json();
    results[step.id] = {
      html: data.contents || data.error || 'No data',
      status: 'done',
      name: step.name,
      nameAr: step.nameAr,
      icon: step.icon
    };
    done++;
  } catch (e) {
    results[step.id] = {
      html: 'Error: ' + e.message,
      status: 'error',
      name: step.name,
      nameAr: step.nameAr,
      icon: step.icon
    };
    errors++;
  }
}

return [{
  json: {
    intent: intent,
    results: results,
    done: done,
    errors: errors,
    pipeline: pipeline,
    siteUrl: siteUrl,
    isAr: isAr
  }
}];

// ===== OBSERVE ENGINE =====
// Analyzes tool results and generates structured report

const input = $input.first().json;
const intent = input.intent;
const results = input.results || {};
const done = input.done || 0;
const errors = input.errors || 0;
const pipeline = input.pipeline || [];
const isAr = input.isAr !== false;
const siteUrl = input.siteUrl || '';

const criticalIssues = [];
const warnings = [];
const passed = [];
const observations = [];

// Helper: extract text from HTML
function getText(html) {
  if (!html) return '';
  return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

// Helper: extract number from text
function extractNum(text, pattern) {
  const m = text.match(pattern);
  return m ? parseInt(m[1].replace(/,/g, '')) : null;
}

// Analyze each tool result
for (const step of pipeline) {
  const r = results[step.id];
  if (!r || r.status !== 'done') continue;
  const text = getText(r.html);
  const icon = step.icon || '';
  const name = isAr ? step.nameAr : step.name;

  switch (step.id) {
    case 'score': {
      const sc = extractNum(text, /(\d{1,3})/);
      if (sc !== null) {
        observations.push({ tool: name, finding: 'Score: ' + sc + '/100', severity: sc >= 80 ? 'pass' : (sc >= 50 ? 'warn' : 'critical') });
        if (sc < 50) criticalIssues.push(icon + ' ' + (isAr ? 'النتيجة منخفضة جداً' : 'Score is very low') + ' (' + sc + '/100)');
        else if (sc < 80) warnings.push(icon + ' ' + (isAr ? 'النتيجة متوسطة' : 'Score is average') + ' (' + sc + '/100)');
        else passed.push(icon + ' ' + (isAr ? 'نتيجة ممتازة' : 'Excellent score') + ' (' + sc + '/100)');
      }
      break;
    }
    case 'meta': {
      if (text.indexOf('Title: N/A') !== -1 || text.indexOf('العنوان: N/A') !== -1 || text.indexOf('No title') !== -1) criticalIssues.push(icon + ' ' + (isAr ? 'العنوان (Title Tag) مفقود' : 'Missing Title Tag'));
      else passed.push(icon + ' ' + (isAr ? 'العنوان موجود' : 'Title tag present'));
      if (text.indexOf('Description: N/A') !== -1 || text.indexOf('الوصف: N/A') !== -1 || text.indexOf('No description') !== -1) criticalIssues.push(icon + ' ' + (isAr ? 'الوصف مفقود' : 'Missing Meta Description'));
      else passed.push(icon + ' ' + (isAr ? 'الوصف موجود' : 'Meta description present'));
      break;
    }
    case 'headings': {
      if (text.indexOf('H1') === -1 || text.indexOf('No H1') !== -1) criticalIssues.push(icon + ' ' + (isAr ? 'لا يوجد عنوان H1' : 'Missing H1 heading'));
      else passed.push(icon + ' ' + (isAr ? 'عنوان H1 موجود' : 'H1 heading present'));
      break;
    }
    case 'images': {
      const altM = text.match(/(\d+)\s*(?:missing|بدون|sans)/i);
      if (altM && parseInt(altM[1]) > 0) warnings.push(icon + ' ' + altM[1] + ' ' + (isAr ? 'صورة بدون نص بديل' : 'images missing alt text'));
      else passed.push(icon + ' ' + (isAr ? 'جميع الصور لها نص بديل' : 'All images have alt text'));
      break;
    }
    case 'links': {
      const bm = text.match(/(\d+)\s*(?:broken|dead|404)/i);
      if (bm && parseInt(bm[1]) > 0) criticalIssues.push(icon + ' ' + bm[1] + ' ' + (isAr ? 'رابط مكسور' : 'broken links'));
      break;
    }
    case 'speed': {
      if (text.indexOf('404') !== -1) warnings.push(icon + ' ' + (isAr ? 'فحص السرعة أخطأ' : 'Speed check failed'));
      else passed.push(icon + ' ' + (isAr ? 'فحص السرعة تم' : 'Speed check OK'));
      break;
    }
    case 'schema': {
      if (text.indexOf('No schema') !== -1 || text.indexOf('لم يتم') !== -1 || text.indexOf('not found') !== -1) warnings.push(icon + ' ' + (isAr ? 'لا يوجد Structured Data' : 'No Structured Data found'));
      else passed.push(icon + ' ' + (isAr ? 'Structured Data موجود' : 'Structured Data present'));
      break;
    }
    case 'robots': {
      if (text.indexOf('Not Found') !== -1 || text.indexOf('غير موجود') !== -1) warnings.push(icon + ' ' + (isAr ? 'robots.txt غير موجود' : 'robots.txt not found'));
      else passed.push(icon + ' ' + (isAr ? 'robots.txt موجود' : 'robots.txt present'));
      break;
    }
    case 'sitemap': {
      if (text.indexOf('Not Found') !== -1 || text.indexOf('غير موجود') !== -1) warnings.push(icon + ' ' + (isAr ? 'Sitemap غير موجود' : 'Sitemap not found'));
      else passed.push(icon + ' ' + (isAr ? 'Sitemap موجود' : 'Sitemap present'));
      break;
    }
    case 'content': {
      const wc = extractNum(text, /(\d[\d,]*)\s*(words|كلمة|word)/i);
      if (wc !== null) {
        if (wc < 300) warnings.push(icon + ' ' + (isAr ? 'المحتوى قصير' : 'Content is thin') + ' (' + wc + ' ' + (isAr ? 'كلمة' : 'words') + ')');
        else passed.push(icon + ' ' + (isAr ? 'المحتوى كافٍ' : 'Content is sufficient') + ' (' + wc + ' ' + (isAr ? 'كلمة' : 'words') + ')');
      }
      break;
    }
  }
}

// Build report HTML
let report = '';
report += '<b>' + (isAr ? 'تقرير التحليل' : 'Analysis Report') + '</b> - ' + siteUrl + '<br><br>';
report += '&#128202; ' + (isAr ? 'تم تنفيذ' : 'Executed') + ': <b>' + done + '/' + pipeline.length + '</b> ' + (isAr ? 'أدوات' : 'tools');
if (errors > 0) report += ' (' + errors + ' ' + (isAr ? 'أخطاء' : 'errors') + ')';

if (passed.length > 0) {
  report += '<br><br>&#9989; <b>' + (isAr ? 'الإيجابيات:' : 'Passed:') + '</b><br>';
  for (let i = 0; i < Math.min(passed.length, 8); i++) report += '&#8226; ' + passed[i] + '<br>';
}
if (warnings.length > 0) {
  report += '<br>&#9888;&#65039; <b>' + (isAr ? 'تحذيرات:' : 'Warnings:') + '</b><br>';
  for (let i = 0; i < Math.min(warnings.length, 8); i++) report += '&#8226; ' + warnings[i] + '<br>';
}
if (criticalIssues.length > 0) {
  report += '<br>&#128308; <b>' + (isAr ? 'مشاكل حرجة:' : 'Critical Issues:') + '</b><br>';
  for (let i = 0; i < Math.min(criticalIssues.length, 8); i++) report += '&#8226; ' + criticalIssues[i] + '<br>';
}

// Recommendations
const recs = [];
if (criticalIssues.length > 0) recs.push(isAr ? '&#128680; يُنصح بإصلاح المشاكل الحرجة فوراً' : '&#128680; Fix critical issues immediately');
if (warnings.length > 2) recs.push(isAr ? '&#128200; هناك مجال واسع للتحسين' : '&#128200; Significant room for improvement');
if (passed.length > 3 && criticalIssues.length === 0) recs.push(isAr ? '&#127881; الموقع في حالة جيدة!' : '&#127881; Site is in good shape!');
if (passed.length === 0 && warnings.length === 0 && criticalIssues.length === 0) recs.push(isAr ? '&#128533; لا توجد بيانات كافية للتحليل' : '&#128533; Insufficient data for analysis');

if (recs.length > 0) {
  report += '<br><br>&#128161; <b>' + (isAr ? 'التوصيات:' : 'Recommendations:') + '</b><br>';
  for (let i = 0; i < recs.length; i++) report += recs[i] + '<br>';
}

// Determine next chips
const chips = [];
if (criticalIssues.length > 0) chips.push(isAr ? 'إصلاح المشاكل' : 'Fix Issues');
chips.push(isAr ? 'تقرير مفصل' : 'Full Report');
if (warnings.length > 0) chips.push(isAr ? 'تحليل المحتوى' : 'Content');
chips.push(isAr ? 'بحث كلمات' : 'KW Research');
chips.push(isAr ? 'تحليل آخر' : 'Analyze Another');

return [{
  json: {
    type: 'report',
    report: report,
    chips: chips,
    passed: passed.length,
    warnings: warnings.length,
    critical: criticalIssues.length,
    done: done,
    total: pipeline.length,
    siteUrl: siteUrl,
    isAr: isAr
  }
}];
